Type mismatch: After simplification, term
  Model.addDyadic_alignLeftOffset 150 hiSign loSign hi lo ehi elo hhi hlo hlt
 has type
  @Eq FloatLib.Numerics.Dyadic
    (Model.addDyadic { negative := hiSign, significand := hi, exponent := ↑ehi - ↑150 }
      { negative := loSign, significand := lo, exponent := ↑elo - ↑150 })
    (Model.addDyadic { negative := hiSign, significand := hi <<< (ehi - elo), exponent := ↑elo - ↑150 }
      { negative := loSign, significand := lo, exponent := ↑elo - ↑150 })
but is expected to have type
  @Eq FloatLib.Numerics.Dyadic
    (Model.addDyadic { negative := hiSign, significand := hi, exponent := ↑ehi - 150 }
      { negative := loSign, significand := lo, exponent := ↑elo - 150 })
    (Model.addDyadic { negative := hiSign, significand := hi <<< (ehi - elo), exponent := ↑elo - 150 }
      { negative := loSign, significand := lo, exponent := ↑elo - 150 })

Type mismatch: After simplification, term
  Model.addDyadic_sameSign_sameExponent hiSign (hi <<< (ehi - elo)) lo (↑elo - 150) hshift hlo0
 has type
  @Eq FloatLib.Numerics.Dyadic
    (Model.addDyadic { negative := hiSign, significand := hi <<< (ehi - elo), exponent := ↑elo - 150 }
      { negative := hiSign, significand := lo, exponent := ↑elo - 150 })
    { negative := hiSign, significand := hi <<< (ehi - elo) + lo, exponent := ↑elo - 150 }
but is expected to have type
  @Eq FloatLib.Numerics.Dyadic
    (Model.addDyadic { negative := hiSign, significand := hi <<< (ehi - elo), exponent := ↑elo - 150 }
      { negative := hiSign, significand := lo, exponent := ↑elo - 150 })
    { negative := hiSign, significand := if True then hi <<< (ehi - elo) + lo else hi <<< (ehi - elo) - lo,
      exponent := ↑elo - 150 }

